// Currency metadata for CurrNow.
// Curated entries have a proper symbol + brand colour; every other
// ISO code still gets a readable name and an auto-generated colour so
// the full API list (160+) can be displayed cleanly.

export type Currency = { code: string; name: string; symbol: string; color: string };

// A palette used to deterministically colour non-curated currencies.
const AUTO_COLORS = [
  '#3C7896', '#5A8C64', '#8C6432', '#7A5AA0', '#B4643C', '#46828C',
  '#8C4664', '#3C9650', '#5A64B4', '#B4503C', '#3C825A', '#967846',
  '#6E5AA0', '#3C82A0', '#A05A5A', '#4664A0', '#787850', '#C8783C',
];

export function autoColor(code: string): string {
  let h = 0;
  for (let i = 0; i < code.length; i++) h = (h * 31 + code.charCodeAt(i)) >>> 0;
  return AUTO_COLORS[h % AUTO_COLORS.length];
}

