const CURATED_CODES = new Set(CURATED.map((c) => c.code));

// Build the full list from the API's rate keys: curated first (nice),
// then everything else alphabetically with a readable name + auto colour.
export function buildCurrencyList(rateCodes: string[]): Currency[] {
  const extras: Currency[] = rateCodes
    .filter((code) => !CURATED_CODES.has(code))
    .sort()
    .map((code) => ({
      code,
      name: ISO_NAMES[code] || code,
      symbol: code.slice(0, 2),
      color: autoColor(code),
    }));
  return [...CURATED, ...extras];
}
